import math
from functools import reduce
import operator

# Helper functions for GCD and LCM
def gcd(a, b):
    return math.gcd(a, b)

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def list_gcd(numbers):
    if not numbers:
        return 0 # Or handle based on context, but here we expect non-empty sets
    return reduce(gcd, numbers)

def list_lcm(numbers):
    if not numbers:
        return 1 # LCM of an empty set is usually 1 for positive integers
    return reduce(lcm, numbers)

def calculate_good_partitions(n):
    if n < 4:
        # As derived, n=2, 3 do not yield sequences satisfying a1 < ... < an
        # for the specific structure, or they are too trivial.
        return 0

    # 1. Define the sequence A = (1, 2, ..., n-1, L_{n-1})
    # L_{n-1} = lcm(1, 2, ..., n-1)
    a_n = list_lcm(list(range(1, n)))
    A = list(range(1, n)) + [a_n]

    count = 0

    # Iterate k from 1 to n-1
    for k in range(1, n):
        A_k = A[:k]
        B_k = A[k:]

        # Calculate LCM of A_k
        lcm_Ak = list_lcm(A_k)

        # Calculate GCD of B_k
        gcd_Bk = list_gcd(B_k)

        # Check for good partition
        if lcm_Ak == gcd_Bk:
            count += 1

    return count

# Calculate C(n) for n up to 15
results = {}
for n in range(4, 16):
    C_n = calculate_good_partitions(n)
    results[n] = C_n
    print(f"C({n}) = {C_n}")

print("\\nResults Dictionary:", results)
